INSERT INTO `pergunta` VALUES (2,6,'(Uncisal 2012) Observe o trecho da música “Admirável Gado Novo”, de Zé Ramalho, e perceba que sua análise pode nos levar a discutir o conceito de alienação.\r\n\r\nO povo foge da ignorância\r\nApesar de viver tão perto dela\r\nE sonha com melhores tempos idos\r\nContemplam essa vida numa cela…\r\nEspera nova possibilidade\r\nDe ver este mundo se acabar\r\nA Arca de Noé, o dirigível\r\nNão voam nem se pode flutuar\r\n\r\nSeguindo o pensamento de Karl Marx, veremos que a alienação se dá em uma situação determinada que gera toda uma gama de desdobramentos e consequências. Tal situação ocorre na esfera',3);
/*!40000 ALTER TABLE `pergunta` ENABLE KEYS */;
